package com.pipepatrol;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@RestController @RequestMapping("/api")
public class PatrolController {
 public record Node(String id,int x,int y,String label,Double lng,Double lat){public Node(String id,int x,int y,String label){this(id,x,y,label,null,null);}}
 public record Pipe(String id,String from,String to,int length,int diameter,String status,boolean directed,String material){public Pipe(String id,String from,String to,int length,int diameter,String status){this(id,from,to,length,diameter,status,false,"PVC-U");}}
 public static class Task {public String id,name,worker,device,status,start,end,note="",weather="dry";public List<String> pipes=new ArrayList<>();public int progress;public String createdAt=Instant.now().toString(),startedAt="",finishedAt="",videoUrl="";public long workedSeconds;public String resumedAt="";public List<String> via=new ArrayList<>(),avoid=new ArrayList<>();public int minDiameter;public boolean flowOnly;}
 public static class Alert {public String id,task,level,text,at;public boolean ack;}
 public static class Device {public String id,name,lastSeen="";public boolean online;public double battery=100,distance,temperature=25;}
 public record Message(String id,String task,String text,String at,String sender,boolean acknowledged){public Message(String id,String task,String text,String at){this(id,task,text,at,"admin",false);}}
 public record Event(String id,String task,String actor,String action,String text,String at){}
 public static class State {public List<Node> nodes=new ArrayList<>();public List<Pipe> pipes=new ArrayList<>();public List<Task> tasks=new ArrayList<>();public List<Alert> alerts=new ArrayList<>();public List<Device> devices=new ArrayList<>();public List<Message> messages=new ArrayList<>();public List<Event> events=new ArrayList<>();public String networkSource="内置示例管网";public boolean demo=true;}
 public record User(String role,String name,Instant expires){}
 public record Login(String username,String password){}
 public record RouteInput(String start,String end,List<String> via,List<String> avoid,Integer minDiameter,Boolean flowOnly){public RouteInput(String start,String end){this(start,end,List.of(),List.of(),0,false);}}
 public record TaskInput(String name,String start,String end,String worker,String device,List<String> via,List<String> avoid,Integer minDiameter,Boolean flowOnly){}
 public record Action(String action,String note,String weather){}
 public record Text(String text){}
 public record Telemetry(String device,String task,double battery,double distance,double temperature,String alarm){}
 @Value("${pipe.data}") String file;
 @Value("${pipe.admin-password}") String adminPassword;
 @Value("${pipe.worker-password}") String workerPassword;
 @Value("${pipe.device-key}") String deviceKey;
 final ObjectMapper mapper; final PatrolDatabase db; State state; final Map<String,User> sessions=new ConcurrentHashMap<>();
 public PatrolController(ObjectMapper mapper,PatrolDatabase db){this.mapper=mapper;this.db=db;}
 @PostConstruct public synchronized void init() throws Exception {db.open(file);db.bootstrap(adminPassword,workerPassword);if(db.hasState())state=db.load();else {Path p=Path.of(file);state=Files.exists(p)?mapper.readValue(p.toFile(),State.class):seed();state.messages=state.messages.stream().map(m->m.sender()==null?new Message(m.id(),m.task(),m.text(),m.at(),"admin",m.acknowledged()):m).collect(java.util.stream.Collectors.toCollection(ArrayList::new));save();} }
 void save(){db.save(state);}
 void event(Task t,User u,String action,String text){state.events.add(new Event(id("E-"),t.id,u.name(),action,text==null?"":text,Instant.now().toString()));}
 void stopClock(Task t){if(!t.resumedAt.isBlank()){t.workedSeconds+=Math.max(0,java.time.Duration.between(Instant.parse(t.resumedAt),Instant.now()).getSeconds());t.resumedAt="";}}
 static IllegalArgumentException bad(String msg){return new IllegalArgumentException(msg);}
 User user(String auth){String token=auth==null?"":auth.replaceFirst("^Bearer ","");User u=sessions.get(token);if(u==null||u.expires().isBefore(Instant.now())||db.accounts().stream().noneMatch(x->x.username().equals(u.name())&&x.enabled()))throw new SecurityException("请重新登录");return u;}
 User admin(String a){User u=user(a);if(!u.role().equals("admin"))throw new UnsupportedOperationException("此操作需要管理人员权限");return u;}
 Task task(String id){return state.tasks.stream().filter(t->t.id.equals(id)).findFirst().orElseThrow(()->bad("任务不存在"));}
 static String id(String prefix){return prefix+UUID.randomUUID().toString().substring(0,8).toUpperCase();}
 @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","UP","service","PipePatrol","displayName","管脉探微——城市无压重力流排水管道低前置条件星闪中继巡检机器人","version","0.1.0");}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Login l){var account=db.authenticate(l.username(),l.password());if(account==null)throw new SecurityException("账号、密码错误或账号已停用");String role=account.role();String token=UUID.randomUUID().toString();sessions.put(token,new User(role,l.username(),Instant.now().plusSeconds(43200)));return Map.of("token",token,"role",role,"name",l.username(),"displayName",account.displayName());}
 @GetMapping("/state") public synchronized State state(@RequestHeader(value="Authorization",required=false)String a){User u=user(a);for(Device d:state.devices)d.online=!d.lastSeen.isBlank()&&Instant.parse(d.lastSeen).isAfter(Instant.now().minusSeconds(15));if(u.role().equals("admin"))return state;State s=new State();s.nodes=state.nodes;s.pipes=state.pipes;s.demo=state.demo;s.networkSource=state.networkSource;s.tasks=state.tasks.stream().filter(t->u.name().equals(t.worker)&&!t.status.equals("draft")&&!t.status.equals("approved")).toList();Set<String> ids=new HashSet<>();s.tasks.forEach(t->ids.add(t.id));s.alerts=state.alerts.stream().filter(x->ids.contains(x.task)).toList();s.messages=state.messages.stream().filter(x->ids.contains(x.task)).toList();Set<String> devices=new HashSet<>();s.tasks.forEach(t->devices.add(t.device));s.devices=state.devices.stream().filter(x->devices.contains(x.id)).toList();s.events=state.events.stream().filter(x->ids.contains(x.task())).toList();return s;}
 @PostMapping("/routes/preview") public synchronized Map<String,Object> route(@RequestHeader("Authorization")String a,@RequestBody RouteInput r){admin(a);return plan(r);}
 Map<String,Object> shortest(String start,String end){return plan(new RouteInput(start,end));}
 Map<String,Object> plan(RouteInput r){
  List<String> way=new ArrayList<>();way.add(r.start());if(r.via()!=null)way.addAll(r.via());way.add(r.end());if(way.size()>32)throw bad("途经检查井最多30个");
  Set<String> ids=new HashSet<>();state.nodes.forEach(n->ids.add(n.id()));for(String n:way)if(n==null||!ids.contains(n))throw bad("检查井编号无效");
  if(Objects.equals(r.start(),r.end())&&(r.via()==null||r.via().isEmpty()))throw bad("请选择两个不同的检查井");
  Set<String> avoid=new HashSet<>(r.avoid()==null?List.of():r.avoid());for(String p:avoid)if(state.pipes.stream().noneMatch(x->x.id().equals(p)))throw bad("避让管段不存在");
  int min=r.minDiameter()==null?0:r.minDiameter();if(min<0||min>3000)throw bad("管径限制无效");
  List<String> path=new ArrayList<>();long total=0;List<Map<String,Object>> legs=new ArrayList<>();
  for(int i=0;i<way.size()-1;i++){String start=way.get(i),end=way.get(i+1);if(start.equals(end))continue;
   Map<String,Long>d=new HashMap<>();Map<String,Pipe>prev=new HashMap<>();Set<String>visited=new HashSet<>();d.put(start,0L);
   while(true){String u=d.keySet().stream().filter(n->!visited.contains(n)).min(Comparator.comparingLong(d::get)).orElse(null);if(u==null||u.equals(end))break;visited.add(u);
    for(Pipe p:state.pipes){if(p.status().equals("blocked")||avoid.contains(p.id())||p.diameter()<min)continue;
     boolean directed=p.directed()||Boolean.TRUE.equals(r.flowOnly());String v=p.from().equals(u)?p.to():!directed&&p.to().equals(u)?p.from():null;
     if(v!=null&&d.get(u)+p.length()<d.getOrDefault(v,Long.MAX_VALUE)){d.put(v,d.get(u)+p.length());prev.put(v,p);}}
   }
   if(!d.containsKey(end))throw bad(start+"至"+end+"在当前限制下没有通路");LinkedList<String>leg=new LinkedList<>();String at=end;while(!at.equals(start)){Pipe p=prev.get(at);leg.addFirst(p.id());at=p.from().equals(at)?p.to():p.from();}path.addAll(leg);total+=d.get(end);legs.add(Map.of("start",start,"end",end,"pipes",leg,"length",d.get(end)));
  }
  return Map.of("pipes",path,"length",total,"start",r.start(),"end",r.end(),"legs",legs,"method","Dijkstra · 有序途经井 / 管径 / 避让 / 方向约束");
 }
 @PostMapping("/tasks") public synchronized Task create(@RequestHeader("Authorization")String a,@RequestBody TaskInput in){admin(a);if(in.name()==null||in.name().isBlank()||in.name().length()>80)throw bad("请输入1—80字任务名称");if(db.accounts().stream().noneMatch(x->x.username().equals(in.worker())&&x.role().equals("worker")&&x.enabled()))throw bad("作业人员不存在或已停用");if(state.devices.stream().noneMatch(d->d.id.equals(in.device())))throw bad("设备不存在");Map<String,Object> route=plan(new RouteInput(in.start(),in.end(),in.via(),in.avoid(),in.minDiameter(),in.flowOnly()));Task t=new Task();t.id=id("T-");t.name=in.name();t.start=in.start();t.end=in.end();t.worker=in.worker();t.device=in.device();t.status="draft";t.pipes=new ArrayList<>();for(Object item:(List<?>)route.get("pipes"))t.pipes.add(item.toString());t.via=in.via()==null?new ArrayList<>():in.via();t.avoid=in.avoid()==null?new ArrayList<>():in.avoid();t.minDiameter=in.minDiameter()==null?0:in.minDiameter();t.flowOnly=Boolean.TRUE.equals(in.flowOnly());state.tasks.add(0,t);event(t,user(a),"create","创建巡检任务");save();return t;}
 @PostMapping("/tasks/{id}/action") public synchronized Task action(@RequestHeader("Authorization")String a,@PathVariable String id,@RequestBody Action in){User u=user(a);Task t=task(id);if(!u.role().equals("admin")&&!u.name().equals(t.worker))throw new UnsupportedOperationException("只能处理本人任务");String action=in.action();if(action==null)throw bad("缺少任务动作");switch(action){case "approve"-> {admin(a);require(t,"draft");t.status="approved";}case "dispatch"->{admin(a);require(t,"approved");var check=plan(new RouteInput(t.start,t.end,t.via,t.avoid,t.minDiameter,t.flowOnly));if(!check.get("pipes").equals(t.pipes))throw bad("管网条件已变化，请重新建立任务路线");t.status="dispatched";}case "start"->{if(!u.role().equals("worker"))throw new UnsupportedOperationException("现场启动由作业人员确认");if(!Set.of("dispatched","paused").contains(t.status))throw bad("任务状态不允许开始");if(!"dry".equals(in.weather()))throw bad("雨天和水位异常时任务暂停，请在现场条件恢复后确认");boolean conflict=state.tasks.stream().anyMatch(x->!x.id.equals(t.id)&&x.device.equals(t.device)&&x.status.equals("running"));if(conflict)throw bad("设备已有进行中的任务");t.weather="dry";t.status="running";t.resumedAt=Instant.now().toString();if(t.startedAt.isBlank())t.startedAt=t.resumedAt;}case "pause"->{require(t,"running");stopClock(t);t.status="paused";t.note=in.note()==null?"人工暂停":in.note();}case "finish"->{require(t,"running");if(in.note()==null||in.note().isBlank())throw bad("请填写现场巡检结果");stopClock(t);t.finishedAt=Instant.now().toString();t.status="completed";t.progress=100;t.note=in.note();}case "review"->{admin(a);require(t,"completed");t.status="reviewed";}default->throw bad("未知动作");}event(t,u,action,in.note());save();return t;}
 void require(Task t,String expected){if(!t.status.equals(expected))throw bad("任务当前状态不允许此操作");}
 @PostMapping("/tasks/{id}/messages") public synchronized Message message(@RequestHeader("Authorization")String a,@PathVariable String id,@RequestBody Text text){User u=user(a);Task t=task(id);if(!u.role().equals("admin")&&!t.worker.equals(u.name()))throw new UnsupportedOperationException("无权访问此任务");if(text.text()==null||text.text().isBlank()||text.text().length()>500)throw bad("消息长度为1—500字");Message m=new Message(id("M-"),id,text.text(),Instant.now().toString(),u.name(),false);state.messages.add(0,m);event(t,u,u.role().equals("admin")?"instruction":"feedback",text.text());save();return m;}
 @PostMapping("/alerts/{id}/ack") public synchronized Map<String,Object> ack(@RequestHeader("Authorization")String a,@PathVariable String id){User u=user(a);Alert al=state.alerts.stream().filter(x->x.id.equals(id)).findFirst().orElseThrow(()->bad("告警不存在"));if(!u.role().equals("admin")&&!task(al.task).worker.equals(u.name()))throw new UnsupportedOperationException("无权确认此告警");al.ack=true;event(task(al.task),u,"ack","确认告警："+al.text);save();return Map.of("ok",true);}
 @PostMapping("/device/telemetry") public synchronized Map<String,Object> telemetry(@RequestHeader("X-Device-Key")String key,@RequestBody Telemetry p){if(!deviceKey.equals(key))throw new SecurityException("设备密钥错误");if(!Double.isFinite(p.battery())||p.battery()<0||p.battery()>100||!Double.isFinite(p.distance())||p.distance()<0||!Double.isFinite(p.temperature()))throw bad("遥测数据超出范围");if(p.alarm()!=null&&p.alarm().length()>300)throw bad("告警文本过长");Device d=state.devices.stream().filter(x->x.id.equals(p.device())).findFirst().orElseThrow(()->bad("设备不存在"));Task t=task(p.task());if(!t.device.equals(d.id)||!t.status.equals("running"))throw bad("遥测须关联本设备运行中的任务");d.battery=p.battery();d.distance=p.distance();d.temperature=p.temperature();d.lastSeen=Instant.now().toString();d.online=true;int total=state.pipes.stream().filter(x->t.pipes.contains(x.id())).mapToInt(Pipe::length).sum();t.progress=Math.min(99,(int)(p.distance()/Math.max(total,1)*100));if(p.alarm()!=null&&!p.alarm().isBlank()){if(p.alarm().length()>300)throw bad("告警文本过长");Alert al=new Alert();al.id=id("A-");al.task=t.id;al.level="warning";al.text=p.alarm();al.at=Instant.now().toString();state.alerts.add(0,al);stopClock(t);t.status="paused";}db.telemetry(p);save();return Map.of("ok",true,"taskStatus",t.status);}
 @ExceptionHandler({IllegalArgumentException.class,SecurityException.class,UnsupportedOperationException.class}) public ResponseEntity<Map<String,String>> errors(RuntimeException e){HttpStatus s=e instanceof SecurityException?HttpStatus.UNAUTHORIZED:e instanceof UnsupportedOperationException?HttpStatus.FORBIDDEN:HttpStatus.BAD_REQUEST;return ResponseEntity.status(s).body(Map.of("message",e.getMessage()));}
 State seed(){State s=new State();s.nodes.addAll(List.of(new Node("J01",130,180,"北门检查井"),new Node("J02",360,180,"中央花园北"),new Node("J03",620,180,"东侧入口"),new Node("J04",130,410,"西侧绿地"),new Node("J05",360,410,"中央花园南"),new Node("J06",620,410,"南门检查井"),new Node("J07",830,300,"东区汇流井")));s.pipes.addAll(List.of(new Pipe("P01","J01","J02",42,200,"normal"),new Pipe("P02","J02","J03",48,250,"attention"),new Pipe("P03","J01","J04",35,200,"normal"),new Pipe("P04","J02","J05",39,200,"normal"),new Pipe("P05","J04","J05",43,250,"normal"),new Pipe("P06","J05","J06",46,300,"normal"),new Pipe("P07","J03","J06",38,250,"normal"),new Pipe("P08","J03","J07",32,300,"blocked"),new Pipe("P09","J06","J07",37,300,"normal")));Device d=new Device();d.id="PP-001";d.name="多节巡检样机 · 01";d.battery=86;s.devices.add(d);Task t=new Task();t.id="T-DEMO01";t.name="中央花园支管例行巡检";t.start="J01";t.end="J06";t.device=d.id;t.worker="worker";t.status="dispatched";t.pipes=new ArrayList<>(List.of("P01","P04","P06"));s.tasks.add(t);return s;}
}
